label{color:#bdc9df!important;font-size:12px!important;letter-spacing:.015em;font-weight:600!important}input,select,textarea{background:#0b1426!important;border:1px solid #34415b!important;color:#eff4ff!important;border-radius:10px!important;min-height:42px;max-width:100%;outline:none;transition:border .15s,box-shadow .15s}input:focus,select:focus,textarea:focus{border-color:var(--accent)!important;box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 20%,transparent)!important}input::placeholder,textarea::placeholder{color:#7d8ca7}
button{background:var(--accent)!important;color:#fff!important;border:1px solid transparent!important;border-radius:10px!important;padding:11px 17px!important;font-weight:700!important;box-shadow:0 5px 18px color-mix(in srgb,var(--accent) 26%,transparent);transition:transform .15s,filter .15s;min-height:42px}button:hover{filter:brightness(1.15);transform:translateY(-1px)}button:focus-visible,a:focus-visible{outline:3px solid #f9cb83;outline-offset:3px}button.secondary{background:#2b3853!important;color:#e6ecff!important;box-shadow:none!important}a{color:#a4b2ff}table{width:100%;border-collapse:collapse}th{color:#8fa2c4!important;letter-spacing:.08em;text-transform:uppercase;font-size:11px!important}th,td{border-color:var(--border)!important;padding:13px 10px!important}td{color:#dbe4f6}tbody tr:hover{background:#ffffff08}ul{padding-left:24px}li{padding:5px 0;color:#d6e0f4}.muted,small,.subtitle{color:var(--muted)!important}#notice,.error{color:#ffadad!important}.success{color:#81e6b6!important}.tag{background:#293656!important;color:#dce5ff!important}.panel table{display:block;overflow-x:auto}.app-footer{border-top:1px solid var(--border);display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;color:#879ab9;font-size:12px;padding:26px 0;margin-top:36px}.app-footer strong{color:#c6d1e5}
