</style><style id="executive-metrics-style">
.executive-panel{margin:22px 0 26px;padding:21px;border-radius:18px;background:linear-gradient(125deg,#172443,#0b1428);border:1px solid #344565;color:#f4f7ff;box-shadow:0 14px 34px #03071235}
