@yield('content')<footer class="app-footer"><span><strong>Stockwise</strong> · Built as a portfolio demonstration</span><span>Local development · Not a hosted service</span></footer><script id="executive-metrics-script">
(()=>{
  const heading=document.querySelector('h1');if(!heading)return;
  const panel=document.createElement('section');panel.className='executive-panel';panel.setAttribute('aria-label','Live business overview');
  const title=document.createElement('h2');title.textContent='Business overview';panel.append(title);
  const intro=document.createElement('p');intro.className='metrics-intro';intro.textContent='Live aggregates from your local database · updates after refreshing';panel.append(intro);
  const cards=document.createElement('div');cards.className='metric-list';panel.append(cards);
  const anchor=heading.closest('header')||heading;anchor.insertAdjacentElement('afterend',panel);
  function number(value){return new Intl.NumberFormat('en-GB').format(value)}
  function format(key,val){if(Array.isArray(val))return number(val.reduce((n,x)=>n+Number(x.count||0),0));if(val!==null&&typeof val==='object')return number(Object.values(val).reduce((n,x)=>n+Number(x||0),0));return typeof val==='number'?number(val):String(val)}
  async function update(){try{const response=await fetch('/api/insights',{headers:{'Accept':'application/json'}});if(!response.ok)throw Error('Reporting unavailable');const data=await response.json();cards.replaceChildren();for(const [key,value] of Object.entries(data)){const item=document.createElement('div');item.className='metric-card';const amount=document.createElement('strong');amount.className='metric-value';amount.textContent=format(key,value);const label=document.createElement('span');label.className='metric-label';label.textContent=key.replace(/_/g,' ');item.append(amount,label);cards.append(item)}}catch(e){cards.textContent='Reporting is temporarily unavailable.';cards.className='metric-skeleton'}}
  update();window.addEventListener('focus',update);
})();
</script></body></html>
